INSERT INTO vulnerabilities (id, external_id, title, severity, cvss, package, description, fixed_in_note, published_at) VALUES
('vuln_00444433', 'SIM-2026-0101', 'Unbounded batch size enables memory exhaustion', 'medium', 5.9, 'text-embeddings-inference', 'Requests with very large input arrays can exhaust host memory.', 'Fixed in TEI 1.7', 1791352800),
('vuln_00447188', 'SIM-2026-0119', 'OpenSSL in base image vulnerable to certificate parsing overflow', 'high', 7.5, 'openssl 3.0.13 (base image)', 'Base image ships an OpenSSL version with a known parsing overflow.', 'Rebuilt base in TensorRT-LLM 0.18.1', 1791352800),
('vuln_004503c', 'SIM-2026-0123', 'Log injection via request headers', 'low', 3.1, 'sglang (http server)', 'Unsanitized headers can forge log lines.', 'Fixed in SGLang 0.4.8', 1791352800),
('vuln_0045518d', 'SIM-2026-0155', 'glibc iconv buffer overflow in CUDA base images', 'medium', 6.5, 'glibc 2.35', 'Affects images built on the cuda-12.4 base.', 'Rebuild on cuda-12.6 base', 1791352800),
('vuln_00460293', 'SIM-2026-0133', 'Path traversal in model download helper', 'high', 7.1, 'text-embeddings-inference (hub client)', 'Scanner match on vendored hub client; helper is not reachable in our deployment.', 'n/a', 1791352800),
('vuln_004634f5', 'SIM-2026-0167', 'Prefix-cache timing side channel leaks prompt tokens across tenants', 'high', 7.4, 'vllm (prefix cache)', 'Shared prefix cache hits are observable via response latency.', 'Fixed in vLLM 0.10.0', 1791356400),
('vuln_00468fb', 'SIM-2026-0142', 'Unsafe deserialization in multimodal input loader allows remote code execution', 'critical', 9.8, 'vllm (multimodal loader)', 'Crafted image payloads can trigger deserialization of attacker-controlled objects in the API server process.', 'Fixed in vLLM 0.10.0', 1791378000);
