INSERT INTO sim_cve_feed (id, external_id, payload_json, image_digests_json, publish_at, published) VALUES
('feed_sim_2026_0142', 'SIM-2026-0142', '{"cvss":9.8,"description":"Crafted image payloads can trigger deserialization of attacker-controlled objects in the API server process.","external_id":"SIM-2026-0142","fixed_in_note":"Fixed in vLLM 0.10.0","package":"vllm (multimodal loader)","severity":"critical","title":"Unsafe deserialization in multimodal input loader allows remote code execution"}', '["sha256:f43310523018848f325567e4a1f109668908be0dfb21c614855bb33eaa11f6e5","sha256:1bc8dbeeb5707d5d4744688178557f1cb877ffa0730de354bf8d18173c47eb65","sha256:2ed310db555c72632d5b225aa1adc71abaa38a7c0b0c864890d564e884594185","sha256:7f0ba97bf8ff03b343ba2fb1e7d81f51f6bfc794b8c18c34196349044ccf55db"]', 1791378000, 1),
('feed_sim_2026_0167', 'SIM-2026-0167', '{"cvss":7.4,"description":"Shared prefix cache hits are observable via response latency.","external_id":"SIM-2026-0167","fixed_in_note":"Fixed in vLLM 0.10.0","package":"vllm (prefix cache)","severity":"high","title":"Prefix-cache timing side channel leaks prompt tokens across tenants"}', '["sha256:0f85093644efe61cdda9003545df5e10b168dfc2f6213c2e6ffb0beedb1db207","sha256:b06b319472284e2243a680d49c9d7b4dbbe2b224e29bc112bbdd2554e7004ddb"]', 1791356400, 1),
('feed_sim_2026_0101', 'SIM-2026-0101', '{"cvss":5.9,"description":"Requests with very large input arrays can exhaust host memory.","external_id":"SIM-2026-0101","fixed_in_note":"Fixed in TEI 1.7","package":"text-embeddings-inference","severity":"medium","title":"Unbounded batch size enables memory exhaustion"}', '["sha256:7e036059c356194ee9d257843d49a229fccf5f3ac24240d1999fdd8f5bcf2149"]', 1791352800, 1),
('feed_sim_2026_0119', 'SIM-2026-0119', '{"cvss":7.5,"description":"Base image ships an OpenSSL version with a known parsing overflow.","external_id":"SIM-2026-0119","fixed_in_note":"Rebuilt base in TensorRT-LLM 0.18.1","package":"openssl 3.0.13 (base image)","severity":"high","title":"OpenSSL in base image vulnerable to certificate parsing overflow"}', '["sha256:98d83c1b4cc86b8ca9586adb74697b5dbfa3989b720e171a541c2c90c8154cac"]', 1791352800, 1),
('feed_sim_2026_0123', 'SIM-2026-0123', '{"cvss":3.1,"description":"Unsanitized headers can forge log lines.","external_id":"SIM-2026-0123","fixed_in_note":"Fixed in SGLang 0.4.8","package":"sglang (http server)","severity":"low","title":"Log injection via request headers"}', '["sha256:e551a819297f8ceac93a714562ae9ad8b36757c8fb282d47dd63bff21c4d544d","sha256:a38f1d00e74a4ef835876f9c6433372d6d0f22b8b804fa225cee4b6dbc287231"]', 1791352800, 1),
('feed_sim_2026_0155', 'SIM-2026-0155', '{"cvss":6.5,"description":"Affects images built on the cuda-12.4 base.","external_id":"SIM-2026-0155","fixed_in_note":"Rebuild on cuda-12.6 base","package":"glibc 2.35","severity":"medium","title":"glibc iconv buffer overflow in CUDA base images"}', '["sha256:2ed310db555c72632d5b225aa1adc71abaa38a7c0b0c864890d564e884594185","sha256:e551a819297f8ceac93a714562ae9ad8b36757c8fb282d47dd63bff21c4d544d"]', 1791352800, 1),
('feed_sim_2026_0133', 'SIM-2026-0133', '{"cvss":7.1,"description":"Scanner match on vendored hub client; helper is not reachable in our deployment.","external_id":"SIM-2026-0133","fixed_in_note":"n/a","package":"text-embeddings-inference (hub client)","severity":"high","title":"Path traversal in model download helper"}', '["sha256:eeaca013ba1ae2fbf091e3dc3f921f6158c1b22fee15f44853cb71988d4d6a1e"]', 1791352800, 1),
('feed_sim_2026_0171', 'SIM-2026-0171', '{"cvss":9.1,"description":"Malformed TIFF images trigger a heap overflow during preprocessing.","external_id":"SIM-2026-0171","fixed_in_note":"Fixed upstream; no SGLang release yet","package":"pillow-simd 9.5","severity":"critical","title":"Heap overflow in image preprocessing (Pillow-SIMD)"}', '["sha256:417f0b16b1d42d6cfec8be53d4fe8b48b493c7585ab569dde2aaf8d7691aa847","sha256:749d9415c3926c0979186d35eb609fc686ea65973c905c8e189f531ae416d1f7"]', NULL, 0);
